"""Post-hoc association uses only generated bytes; no real model or private input."""
import json
import os
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

import numpy as np
from PIL import Image

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import bind_scene_identity as binder
import suggest as s
from artifact_identity import file_sha256
from scan_core import SPLAT_DTYPE, build_metadata

CREATED = '2026-10-18T00:00:00.000Z'
BEFORE_NS = 1792195200 * 1_000_000_000  # 2026-10-17 UTC


def make_legacy_run(root, version=2):
    root = Path(root)
    images = root/'work/dataset/images'; images.mkdir(parents=True)
    names = ['000001.jpg', '000002.jpg']
    for name in names:
        path = images/name; Image.new('RGB', (20, 20), (60,80,100)).save(path)
        os.utime(path, ns=(BEFORE_NS, BEFORE_NS))
    rows = np.zeros(2, dtype=SPLAT_DTYPE)
    rows['position'] = [[0,0,0],[1,0,0]]; rows['scale'] = 1; rows['rgba'] = 255; rows['rotation'] = [255,128,128,128]
    (root/'scene.splat').write_bytes(rows.tobytes()); os.utime(root/'scene.splat', ns=(BEFORE_NS, BEFORE_NS))
    metadata = build_metadata(2, [[-1,-1,-1],[1,1,1]], [0,1,3], [0,0,0], 30,30,1,CREATED)
    (root/'scene.json').write_text(json.dumps(metadata))
    (root/'run.json').write_text(json.dumps({'status':'complete','source':'synthetic fixture; no pipeline execution'}))
    (root/'work/alignment.json').write_text(json.dumps({'source':'synthetic identity alignment','rotationWorldToAligned':np.eye(3).tolist(),'sparseCenterOriginal':[0,0,0]}))
    catalog = s.load_questions()
    observations = {q['checklistItemId']:[{'frame':name,'rawProbability':p,'probability':p,'relevanceProbability':.9} for name,p in zip(names,[.8,.2])] for q in catalog}
    thumbnail = s.image_data(type('Frame', (), {'path':images/names[0], 'width':20, 'height':20, 'name':names[0]})(), 320)
    data = {'format':'fixlist-scan-suggestions','version':2,'createdAt':CREATED,
            'model':{'name':'Synthetic legacy scores; no model invoked','backend':'mlx','engine':'startlux-decision','license':'CC BY-NC 4.0 weights'},
            'scan':{'splatCount':2,'framesAnalyzed':2,'keyframes':names},
            'thresholds':{'suggestion':.6,'location':.5,'relevance':.5,'noneProbability':.2,'minFrames':1},
            'calibration':None, 'notice':s.NOTICE,
            'items':s.aggregate_items(catalog, observations, .6, lambda _:thumbnail),
            'timing':{'totalSeconds':1,'requestSeconds':.5,'requests':2,'attempts':2,'retries':0,'dryRun':0}}
    if version == 1:
        data['version'] = 1; del data['calibration'], data['thresholds']['minFrames']
        for item in data['items']:
            item['maxProbability'] = item.pop('score'); item['suggested'] = item.pop('status') == 'suggested'
            for key in ['relevanceQuestion','limitation','relevantFrames','localization']: del item[key]
            for row in item['perFrame']: del row['rawProbability'], row['relevanceProbability']
    s.validate_output(data)
    (root/'suggestions.json').write_text(json.dumps(data, indent=2)+'\n')
    return data


class BindingTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(); self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name).resolve(); make_legacy_run(self.root)

    def inspect(self): return binder.bind_run(self.root)
    def failed(self, check):
        report = self.inspect(); self.assertFalse(report['wouldBind']); self.assertFalse(report['written'])
        self.assertTrue(any(c['status']=='FAIL' and c['check']==check for c in report['checks']), report['checks'])

    def test_dry_run_computes_actual_hashes_and_changes_no_files(self):
        before = {str(p.relative_to(self.root)):p.read_bytes() for p in self.root.rglob('*') if p.is_file()}
        report = self.inspect()
        self.assertTrue(report['wouldBind']); self.assertFalse(report['written']); self.assertEqual(report['mode'],'dry-run')
        identity = report['identity']
        self.assertEqual(identity['sceneSHA256'], file_sha256(self.root/'scene.splat'))
        self.assertEqual(identity['frames'][0]['sha256'], file_sha256(self.root/'work/dataset/images/000001.jpg'))
        self.assertIn('post-hoc', identity['processing']['producer']); self.assertIsNone(report['modelIdentity'])
        self.assertEqual(before, {str(p.relative_to(self.root)):p.read_bytes() for p in self.root.rglob('*') if p.is_file()})

    def test_write_preserves_original_exactly_and_validates_bound_v1_and_v2(self):
        for version in [1,2]:
            with self.subTest(version=version), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp).resolve(); make_legacy_run(root, version)
                original = (root/'suggestions.json').read_bytes()
                report = binder.bind_run(root, write=True)
                self.assertTrue(report['written']); self.assertEqual((root/report['backup']).read_bytes(), original)
                bound = json.loads((root/'suggestions.json').read_bytes()); s.validate_output(bound)
                self.assertIsNone(bound['model']['identity']); self.assertEqual(bound['scan']['identity'], report['identity'])

    def test_count_mismatch_is_rejected(self):
        data = json.loads((self.root/'suggestions.json').read_bytes()); data['scan']['splatCount'] = 3
        (self.root/'suggestions.json').write_text(json.dumps(data)); self.failed('suggestions-count')

    def test_missing_frame_is_rejected(self):
        (self.root/'work/dataset/images/000001.jpg').unlink()
        self.failed('ordinary-contained:work/dataset/images/000001.jpg')

    def test_symlinked_frame_or_parent_is_rejected(self):
        for parent in [False, True]:
            with self.subTest(parent=parent), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp).resolve(); make_legacy_run(root)
                target = root/'work/dataset/images/000001.jpg'
                if parent:
                    directory = root/'work/dataset/images'; directory.rename(root/'original-images'); directory.symlink_to(root/'original-images', target_is_directory=True)
                else:
                    target.rename(root/'original.jpg'); target.symlink_to(root/'original.jpg')
                report = binder.bind_run(root)
                self.assertFalse(report['wouldBind']); self.assertTrue(any(c['status']=='FAIL' and c['check'].startswith('ordinary-contained:work/dataset/images') for c in report['checks']))

    def test_scene_or_frame_newer_than_inference_is_rejected(self):
        for name, check in [('scene.splat','scene-not-newer'),('work/dataset/images/000001.jpg','frame-not-newer:000001.jpg')]:
            with self.subTest(name=name):
                path = self.root/name; os.utime(path, ns=(1_792_281_600_000_000_001,1_792_281_600_000_000_001))
                self.failed(check); os.utime(path, ns=(BEFORE_NS,BEFORE_NS))

    def test_run_must_be_complete(self):
        (self.root/'run.json').write_text('{"status":"failed"}'); self.failed('completed-run')

    def test_already_bound_file_is_not_rebound_or_backed_up_again(self):
        binder.bind_run(self.root, write=True)
        original = (self.root/'suggestions.json').read_bytes(); backups = list(self.root.glob('*.bak'))
        report = binder.bind_run(self.root, write=True)
        self.assertFalse(report['wouldBind']); self.assertEqual(original,(self.root/'suggestions.json').read_bytes()); self.assertEqual(backups,list(self.root.glob('*.bak')))

    def test_existing_backup_is_never_overwritten(self):
        name = 'suggestions.unbound-fixed.json.bak'; (self.root/name).write_bytes(b'earlier backup')
        original = (self.root/'suggestions.json').read_bytes()
        with patch.object(binder,'backup_name',return_value=name), self.assertRaises(FileExistsError): binder.bind_run(self.root, write=True)
        self.assertEqual((self.root/name).read_bytes(),b'earlier backup'); self.assertEqual((self.root/'suggestions.json').read_bytes(),original)

    def test_atomic_replace_failure_preserves_original_and_backup(self):
        original = (self.root/'suggestions.json').read_bytes()
        with patch.object(binder.os,'replace',side_effect=OSError('synthetic replace failure')), self.assertRaises(OSError): binder.bind_run(self.root, write=True)
        self.assertEqual((self.root/'suggestions.json').read_bytes(),original)
        backups = list(self.root.glob('*.bak')); self.assertEqual(len(backups),1); self.assertEqual(backups[0].read_bytes(),original)
        self.assertEqual(list(self.root.glob('.suggestions-bound-*')),[])

    def test_sources_changed_after_inspection_do_not_receive_binding(self):
        _, bound, snapshots, original = binder.inspect_run(self.root)
        (self.root/'work/dataset/images/000001.jpg').write_bytes(b'changed source')
        with self.assertRaisesRegex(ValueError,'changed after inspection'):
            binder.write_bound(self.root,bound,snapshots,original,'suggestions.unbound-test.json.bak')
        self.assertFalse((self.root/'suggestions.unbound-test.json.bak').exists())

    def test_optional_alignment_absence_is_explicit(self):
        (self.root/'work/alignment.json').unlink(); report = self.inspect()
        self.assertTrue(report['wouldBind']); self.assertIsNone(report['identity']['processing']['alignmentSHA256'])

    def test_calibration_recovery_lists_exact_rescore_refit_and_matching_inference_commands(self):
        hint = s.calibration_recovery_commands('living room')
        self.assertIn('evaluate_model.py score --dataset "$FIXLIST_PINNED_DATASET"', hint)
        self.assertIn('evaluate_model.py fit --dataset "$FIXLIST_PINNED_DATASET"', hint)
        self.assertIn('--out "$FIXLIST_PINNED_DATASET/calibration.pinned.json"', hint)
        self.assertIn("suggest.py 'living room' --calibration", hint)
        self.assertIn('--think-mode never --model-dir "$FIXLIST_MODEL_DIR" --runtime-dir "$FIXLIST_RUNTIME_DIR"', hint)
        self.assertIn("suggest.py 'living room' --no-calibration", hint)
        self.assertIn('experimental uncalibrated scores only', hint)
